package com.ruoyi.web.controller.metal;
import java.util.*;import java.math.BigDecimal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;
import com.ruoyi.common.annotation.Log;import com.ruoyi.common.enums.BusinessType;import com.ruoyi.common.core.domain.AjaxResult;
import com.ruoyi.metal.service.*;import com.ruoyi.metal.security.FactoryScope;import org.springframework.jdbc.core.JdbcTemplate;
import jakarta.servlet.http.HttpServletResponse;import org.apache.poi.xssf.usermodel.XSSFWorkbook;
@RestController @RequestMapping("/metal")
public class WorkOrderFlowExtensionController {
 private final SemiSourcePolicyService policy;private final WorkOrderWeightBalanceService ledger;private final JdbcTemplate jdbc;private final FactoryScope scope;
 public WorkOrderFlowExtensionController(SemiSourcePolicyService p,WorkOrderWeightBalanceService l,JdbcTemplate j,FactoryScope s){policy=p;ledger=l;jdbc=j;scope=s;}
 public record Permit(@NotNull @Positive Long itemId,@Min(1) int sourceSequence,@Min(3) int targetSequence,@NotNull Boolean enabled,@Min(0) Integer version,@NotBlank @Pattern(regexp="[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}") String requestId,@NotBlank @Size(max=500) String reason){}
 @GetMapping("/route-skip-permits") @PreAuthorize("@ss.hasPermi('metal:route-skip:configure')")
 public AjaxResult permits(@RequestParam long itemId){return AjaxResult.success(clean(policy.permits(itemId)));}
 @PostMapping("/route-skip-permits") @PreAuthorize("@ss.hasPermi('metal:route-skip:configure')") @Log(title="新增工艺跳步许可",businessType=BusinessType.INSERT)
 public AjaxResult create(@Valid @RequestBody Permit p){return AjaxResult.success().put("id",String.valueOf(policy.configure(null,p.itemId(),p.sourceSequence(),p.targetSequence(),p.enabled(),p.version(),p.requestId(),p.reason())));}
 @PutMapping("/route-skip-permits/{id}") @PreAuthorize("@ss.hasPermi('metal:route-skip:configure')") @Log(title="修改工艺跳步许可",businessType=BusinessType.UPDATE)
 public AjaxResult change(@PathVariable Long id,@Valid @RequestBody Permit p){policy.configure(id,p.itemId(),p.sourceSequence(),p.targetSequence(),p.enabled(),p.version(),p.requestId(),p.reason());return AjaxResult.success();}
 @GetMapping("/work-order/{id}/weight-balance") @PreAuthorize("@ss.hasPermi('metal:work-order:query')")
 public AjaxResult balance(@PathVariable long id,@RequestParam(required=false) Long itemId){var r=ledger.summary(id,itemId);r.remove("lines");return AjaxResult.success(clean(r));}
 @GetMapping("/work-order/{id}/weight-balance/lines") @PreAuthorize("@ss.hasPermi('metal:work-order:query')")
 public AjaxResult lines(@PathVariable long id,@RequestParam(required=false) Long itemId,@RequestParam(required=false) String category,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="20") int size,@RequestParam String snapshotToken){return AjaxResult.success(clean(ledger.lines(id,itemId,category,page,size,snapshotToken)));}
 @GetMapping("/work-order/{id}/weight-balance/export") @PreAuthorize("@ss.hasPermi('metal:work-order:query') && @ss.hasPermi('metal:work-order:weight-export')") @Log(title="整单重量总账导出",businessType=BusinessType.EXPORT)
 public void export(@PathVariable long id,@RequestParam(required=false) Long itemId,@RequestParam String snapshotToken,HttpServletResponse response)throws Exception{
  var report=ledger.export(id,itemId,snapshotToken);try(var book=new XSSFWorkbook()){var sheet=book.createSheet("整单重量总账");int row=0;var heading=sheet.createRow(row++);heading.createCell(0).setCellValue(String.valueOf(report.get("workOrderNo")));heading.createCell(1).setCellValue(String.valueOf(report.get("status")));for(var entry:((Map<String,String>)report.get("totals")).entrySet()){var r=sheet.createRow(row++);r.createCell(0).setCellValue(WorkOrderWeightBalanceService.label(entry.getKey()));r.createCell(1).setCellValue(entry.getValue());}var h=sheet.createRow(row++);String[] titles={"类别","单据/批次","物料编号","物料名称","净重(g)","数量(件)"};for(int i=0;i<titles.length;i++)h.createCell(i).setCellValue(titles[i]);for(var line:(List<Map<String,Object>>)report.get("lines")){var r=sheet.createRow(row++);String[] fields={"category","orderNo","code","name","weight","quantity"};for(int i=0;i<fields.length;i++)r.createCell(i).setCellValue(i==0?WorkOrderWeightBalanceService.label(Objects.toString(line.get(fields[i]),"—")):Objects.toString(line.get(fields[i]),"—"));}for(String warning:(List<String>)report.get("anomalies"))sheet.createRow(row++).createCell(0).setCellValue(warning);for(int i=0;i<6;i++)sheet.setColumnWidth(i,7000);response.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");response.setHeader("Content-Disposition","attachment; filename=work-order-weight.xlsx");book.write(response.getOutputStream());}
 }
 @GetMapping("/work-order/{id}/auto-release") @PreAuthorize("@ss.hasPermi('metal:work-order:query')")
 public AjaxResult auto(@PathVariable long id){var w=jdbc.queryForMap("SELECT factory_id,auto_semi_release_eligible,completion_generation FROM metal_work_order WHERE work_order_id=? AND del_flag='0'",id);scope.check(Long.valueOf(w.get("factory_id").toString()));var events=jdbc.queryForList("SELECT * FROM metal_semi_auto_release_event WHERE work_order_id=? AND generation=?",id,w.get("completion_generation"));var out=new LinkedHashMap<String,Object>(w);out.remove("factory_id");if(!events.isEmpty()){out.put("event",events.get(0));out.put("results",jdbc.queryForList("SELECT * FROM metal_semi_auto_release_result WHERE event_id=? ORDER BY inventory_id",events.get(0).get("event_id")));}return AjaxResult.success(clean(out));}
 private static Object clean(Object value){if(value instanceof Map<?,?> m){var out=new LinkedHashMap<String,Object>();m.forEach((k,v)->{if(k.toString().matches("[A-Z_]+")){out.put(k.toString(),clean(v));return;}StringBuilder n=new StringBuilder();boolean upper=false;for(char c:k.toString().toCharArray()){if(c=='_'){upper=true;continue;}n.append(upper?Character.toUpperCase(c):c);upper=false;}String key=n.toString();out.put(key,v!=null&&(key.endsWith("Id")||key.equals("id"))?v.toString():clean(v));});return out;}if(value instanceof List<?> l)return l.stream().map(WorkOrderFlowExtensionController::clean).toList();return value instanceof BigDecimal d?d.toPlainString():value;}
}
